  using(var f=Skin.Font(8,true))Skin.Text(g,(c.Pinned?"★ 收藏   ·   ":"")+(c.Kind=="image"?"图片":"文本")+"   "+c.Time.ToString("MM-dd HH:mm"),f,selected?Color.FromArgb(153,103,25):Skin.Muted,new RectangleF(r.X+15,r.Y+10,r.Width-30,20));
  using(var f=Skin.Font(10))using(var sf=new StringFormat{Trimming=StringTrimming.EllipsisCharacter})Skin.Text(g,c.Summary,f,Skin.Ink,new RectangleF(r.X+15,r.Y+33,r.Width-30,43),sf);
