 Clip Selected(){return list.SelectedItem as Clip;}
 public void RefreshList(){var selected=Selected();list.BeginUpdate();list.Items.Clear();foreach(var c in History.Items.Where(c=>(filter=="all"||filter==c.Kind||filter=="pinned"&&c.Pinned)&&(c.Kind=="image"?search.Text.Length==0||"图片".Contains(search.Text):c.Value.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0)).OrderByDescending(c=>c.Pinned).ThenByDescending(c=>c.Time))list.Items.Add(c);list.EndUpdate();if(selected!=null&&list.Items.Contains(selected))list.SelectedItem=selected;else if(list.Items.Count>0)list.SelectedIndex=0;else ShowPreview();countLabel.Text=History.Items.Count+" 份灵感";status.Text="Ctrl+Alt+V 打开  ·  双击 / Enter 粘贴  ·  本机加密保存";if(quick!=null)quick.RefreshClips(History.Items);}
 void ShowPreview(){var c=Selected();var old=picture.Image;picture.Image=null;if(old!=null)old.Dispose();picture.Visible=c!=null&&c.Kind=="image";preview.Visible=!picture.Visible;preview.Text=c==null?"口袋还是空的。\r\n\r\n复制一段文字或一张图片，让袋袋替你收好。":c.Kind=="text"?c.Value:"";if(picture.Visible)try{using(var ms=new MemoryStream(Convert.FromBase64String(c.Value)))using(var im=Image.FromStream(ms))picture.Image=new Bitmap(im);}catch{picture.Visible=false;preview.Visible=true;preview.Text="图片无法预览。";}}
 void DeleteSelected(){var c=Selected();if(c!=null){History.Items.Remove(c);Persist();RefreshList();}}
 void Persist(){try{History.Save();}catch(Exception ex){status.Text="保存失败："+ex.Message;}}
 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);if(demo)return;listenerRegistered=Native.AddClipboardFormatListener(Handle);hotkeyRegistered=Native.RegisterHotKey(Handle,1,0x4003,0x56);if(!hotkeyRegistered)BeginInvoke((Action)(()=>MessageBox.Show("Ctrl+Alt+V 被其他程序占用，可从托盘或袋袋打开历史。")));if(!listenerRegistered)BeginInvoke((Action)(()=>MessageBox.Show("剪贴板监听注册失败，请重启简贴。")));}
 protected override void WndProc(ref Message m){if(m.Msg==0x312){if(Visible&&Native.GetForegroundWindow()==Handle)Hide();else OpenPanel();}if(m.Msg==0x31D){retries=0;retry.Stop();retry.Start();}base.WndProc(ref m);}
 void CaptureClipboard(){if(demo||pause.Checked||Native.GetClipboardSequenceNumber()==ownSequence)return;try{uint seq=Native.GetClipboardSequenceNumber();var d=Clipboard.GetDataObject();if(d==null||Native.Excluded(d))return;Clip c=null;if(d.GetDataPresent(DataFormats.Bitmap)){using(var im=Clipboard.GetImage()){if(im==null)return;using(var ms=new MemoryStream()){im.Save(ms,System.Drawing.Imaging.ImageFormat.Png);if(ms.Length>4*1024*1024){status.Text="图片超过 4 MB，未记录";return;}c=new Clip{Kind="image",Value=Convert.ToBase64String(ms.ToArray()),Time=DateTime.Now};}}}else if(d.GetDataPresent(DataFormats.UnicodeText)){string text=d.GetData(DataFormats.UnicodeText) as string;if(string.IsNullOrWhiteSpace(text)||text.Length>500000)return;c=new Clip{Kind="text",Value=text,Time=DateTime.Now};}if(c==null)return;if(Native.GetClipboardSequenceNumber()!=seq){if(++retries<8)retry.Start();return;}if(History.Add(c)){Persist();RefreshList();if(pet!=null)pet.CaptureClip(c);}else status.Text="口袋已满，请取消部分收藏或删除旧内容。";}catch(ExternalException){if(++retries<8)retry.Start();}catch(Exception ex){status.Text="记录失败："+ex.Message;}}
 public void PasteClip(Clip c,bool paste){if(c==null)return;try{
  if(c.Kind=="text")Clipboard.SetText(c.Value);else using(var ms=new MemoryStream(Convert.FromBase64String(c.Value)))using(var im=Image.FromStream(ms))Clipboard.SetImage(im);ownSequence=Native.GetClipboardSequenceNumber();PetReact("wave","拿好啦，送给正在专注的你。",3);
  if(!paste)return;Hide();HideQuick();IntPtr destination=target;uint seq=ownSequence;
  if(destination==IntPtr.Zero||!Native.IsWindow(destination)||!Native.External(destination)){PasteFallback();return;}
  Native.SetForegroundWindow(destination);pendingWait=0;var timer=new Timer{Interval=60};timer.Tick+=delegate{pendingWait++;if(Native.GetForegroundWindow()!=destination||Native.GetClipboardSequenceNumber()!=seq){timer.Stop();timer.Dispose();PasteFallback();return;}if(Native.ModifiersDown()){if(pendingWait>25){timer.Stop();timer.Dispose();PasteFallback();}return;}if(pendingWait<3)return;timer.Stop();timer.Dispose();try{SendKeys.SendWait("^v");}catch{PasteFallback();}};timer.Start();
 }catch(Exception ex){MessageBox.Show("复制失败："+ex.Message,"简贴");}}
 void PasteFallback(){PetReact("wave","已复制好，按 Ctrl+V 就能粘贴。",5);if(tray!=null&&tray.Visible)tray.ShowBalloonTip(2000,"内容已复制","请回到输入框按 Ctrl+V 粘贴。",ToolTipIcon.Info);}
 public void CollectText(string value){if(pause.Checked||string.IsNullOrWhiteSpace(value)||value.Length>500000)return;var c=new Clip{Kind="text",Value=value,Time=DateTime.Now};if(History.Add(c)){Persist();RefreshList();if(pet!=null)pet.CaptureClip(c);}}
