 protected override void Dispose(bool disposing){if(disposing&&!resourcesDisposed){resourcesDisposed=true;watch.Dispose();retry.Dispose();CloseKnowledge();if(Library!=null)Library.Dispose();if(listenerRegistered&&IsHandleCreated)Native.RemoveClipboardFormatListener(Handle);if(hotkeyRegistered&&IsHandleCreated)Native.UnregisterHotKey(Handle,1);if(pet!=null)pet.Dispose();if(quick!=null)quick.Dispose();if(toast!=null)toast.Dispose();if(settingsWindow!=null)settingsWindow.Dispose();if(tray!=null){tray.Visible=false;tray.ContextMenuStrip.Dispose();tray.Dispose();}if(picture.Image!=null)picture.Image.Dispose();if(appIcon!=null)appIcon.Dispose();}base.Dispose(disposing);}
